#if UNITY_EDITOR
using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;
public class SkyRuinMesh {
public List<Vector3> v=new List<Vector3>();public List<int> tri=new List<int>();public List<Vector2> uv=new List<Vector2>();
public void Face(params Vector3[] p){int b=v.Count;Vector3 normal=Vector3.Cross(p[1]-p[0],p[2]-p[0]).normalized;foreach(var q in p){v.Add(q);uv.Add(Mathf.Abs(normal.y)>.5f?new Vector2(q.x,q.z)*.27f:new Vector2(q.x+q.z,q.y)*.27f);}for(int i=1;i<p.Length-1;i++){tri.Add(b);tri.Add(b+i);tri.Add(b+i+1);}}
public void Slab(Vector3[] poly,float height,float bevel=.06f){Vector3 c=Vector3.zero;foreach(var p in poly)c+=p;c/=poly.Length;var top=new Vector3[poly.Length];var low=new Vector3[poly.Length];for(int i=0;i<poly.Length;i++){var d=poly[i]-c;float k=Mathf.Max(.6f,1-bevel/Mathf.Max(.01f,d.magnitude));top[i]=c+d*k;low[i]=poly[i]-Vector3.up*bevel;}Face(top);for(int i=0;i<poly.Length;i++){int j=(i+1)%poly.Length;Face(top[i],low[i],low[j],top[j]);Face(low[i],poly[i]-Vector3.up*height,poly[j]-Vector3.up*height,low[j]);}var bot=new Vector3[poly.Length];for(int i=0;i<poly.Length;i++)bot[i]=poly[poly.Length-1-i]-Vector3.up*height;Face(bot);}
public void Block(Vector3 center,float width,float depth,float height,float yaw=0,float bevel=.07f){var rot=Quaternion.Euler(0,yaw,0);var pts=new[]{new Vector3(-width/2,0,-depth/2),new Vector3(-width/2,0,depth/2),new Vector3(width/2,0,depth/2),new Vector3(width/2,0,-depth/2)};for(int i=0;i<4;i++)pts[i]=center+rot*pts[i];Slab(pts,height,bevel);}
public void Wedge(Vector3 c,float inner,float outer,float a,float b,float height,int cuts=3){if(b-a>6.28f){for(int j=0;j<cuts;j++)Wedge(c,inner,outer,Mathf.Lerp(a,b,j/(float)cuts),Mathf.Lerp(a,b,(j+1)/(float)cuts),height,1);return;}var p=new List<Vector3>();for(int i=0;i<=cuts;i++){float t=Mathf.Lerp(a,b,i/(float)cuts);p.Add(c+new Vector3(Mathf.Cos(t)*outer,0,Mathf.Sin(t)*outer));}for(int i=cuts;i>=0;i--){float t=Mathf.Lerp(a,b,i/(float)cuts);p.Add(c+new Vector3(Mathf.Cos(t)*inner,0,Mathf.Sin(t)*inner));}p.Reverse();Slab(p.ToArray(),height,.025f);}
public void Ring(Vector3 c,float r,float width,float height,int segments=64){for(int i=0;i<segments;i++)Wedge(c,r-width/2,r+width/2,i*Mathf.PI*2/segments,(i+1)*Mathf.PI*2/segments,height,1);}
public void Rock(Vector3 c,float radius,float height,int segments,int seed){var rng=new System.Random(seed);var rings=new List<Vector3[]>();float[] yy={0,-height*.18f,-height*.66f,-height};float[] rr={1,1.04f,.67f,.13f};for(int j=0;j<4;j++){var ring=new Vector3[segments];for(int i=0;i<segments;i++){float a=i*Mathf.PI*2/segments;float r=radius*rr[j]*(.86f+(float)rng.NextDouble()*.25f);ring[i]=c+new Vector3(Mathf.Cos(a)*r,yy[j]+(j==0?0:(float)rng.NextDouble()*.7f),Mathf.Sin(a)*r);}rings.Add(ring);}for(int j=0;j<3;j++)for(int i=0;i<segments;i++){int k=(i+1)%segments;Face(rings[j][i],rings[j+1][k],rings[j+1][i]);Face(rings[j][i],rings[j][k],rings[j+1][k]);}var top=rings[0];Array.Reverse(top);Face(top);}
public Mesh Mesh(string name){var m=new Mesh();m.name=name;m.indexFormat=IndexFormat.UInt32;m.SetVertices(v);m.SetTriangles(tri,0);m.SetUVs(0,uv);m.RecalculateNormals();m.RecalculateBounds();return m;}
}
#endif
